import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate, Easing } from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type AnimatedButtonProps = Record<string, any>;

const AnimatedButton: React.FC<AnimatedButtonProps> = ({
  backgroundColor = "#f0f4f8",
  transparentBackground = false,
  durationInSeconds = 4,
  buttonText = "Start Journey",
  buttonColor = "#111827",
  buttonTextColor = "#ffffff",
  cursorColor = "#000000",
}) => {
  {/* Load Google Fonts */}
  useFontLoader(["Inter"]);
  {/* End Load Google Fonts */}

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Logic to prevent parser errors
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;
  const s = Math.min(width, height);

  // --- Animation Timings & Physics ---

  // 1. Button Entrance
  const buttonEntranceScale = spring({
    frame,
    fps,
    config: { damping: 14, mass: 0.8 },
  });
  
  const buttonEntranceOpacity = interpolate(frame, [0, 15], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // 2. Cursor Entrance & Movement
  // Start far off screen to bottom right
  const cursorEnterProgress = spring({
    frame: frame - 25,
    fps,
    config: { damping: 16, mass: 1.2 },
  });

  const targetCursorX = width * 0.5 + width * 0.02; // Offset slightly to right of center
  const targetCursorY = height * 0.5 + height * 0.02; // Offset slightly below center

  const cursorX = interpolate(cursorEnterProgress, [0, 1], [width + 200, targetCursorX]);
  const cursorY = interpolate(cursorEnterProgress, [0, 1], [height + 200, targetCursorY]);

  // 3. Hover Interaction
  const hoverProgress = interpolate(frame, [45, 50], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.ease),
  });

  // 4. Click Interaction
  const clickDown = interpolate(frame, [55, 58, 62, 65], [0, 1, 1, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const cursorScale = interpolate(frame, [55, 58, 62, 65], [1, 0.85, 0.85, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Combine transforms for the button
  const currentButtonScale = buttonEntranceScale + (hoverProgress * 0.03) - (clickDown * 0.06);

  const shadowY = interpolate(hoverProgress, [0, 1], [4, 12]) - (clickDown * 8);
  const shadowBlur = interpolate(hoverProgress, [0, 1], [10, 24]) - (clickDown * 14);
  const shadowOpacity = 0.1 + (hoverProgress * 0.1);

  // 5. Ripple Effect
  const hasClicked = frame >= 58;
  const rippleScaleAnim = spring({
    frame: frame - 58,
    fps,
    config: { damping: 14, mass: 0.6 },
  });
  const rippleOpac = interpolate(frame, [58, 85], [1, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: "Inter, sans-serif" }}>
      
      {/* Ripple Effect Layer */}
      {hasClicked && (
        <div
          style={{
            position: "absolute",
            left: width / 2,
            top: height / 2,
            width: height * 0.15,
            height: height * 0.15,
            marginLeft: -height * 0.075,
            marginTop: -height * 0.075,
            borderRadius: "50%",
            backgroundColor: buttonColor,
            opacity: rippleOpac * 0.3,
            transform: `scale(${rippleScaleAnim * 5})`,
            pointerEvents: "none",
            zIndex: 1,
            transition: "none",
          }}
        />
      )}

      {/* Button Layer */}
      <div
        style={{
          position: "absolute",
          left: 0,
          top: 0,
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          pointerEvents: "none",
          zIndex: 2,
        }}
      >
        <div
          style={{
            backgroundColor: buttonColor,
            padding: `${height * 0.03}px ${width * 0.04}px`,
            borderRadius: height * 0.025,
            transform: `scale(${currentButtonScale})`,
            opacity: buttonEntranceOpacity,
            boxShadow: `0px ${shadowY}px ${shadowBlur}px rgba(0,0,0,${shadowOpacity})`,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            transition: "none",
          }}
        >
          <span
            style={{
              color: buttonTextColor,
              fontSize: s * 0.045,
              fontWeight: 600,
              letterSpacing: "-0.01em",
              transition: "none",
            }}
          >
            {buttonText}
          </span>
        </div>
      </div>

      {/* Cursor Layer */}
      <svg
        width={s * 0.08}
        height={s * 0.08}
        viewBox="0 0 24 24"
        style={{
          position: "absolute",
          left: cursorX,
          top: cursorY,
          transform: `scale(${cursorScale}) rotate(-5deg)`,
          filter: "drop-shadow(0px 4px 6px rgba(0,0,0,0.3))",
          zIndex: 10,
          transition: "none",
        }}
      >
        <path
          d="M4 2 L4 21.5 L9.5 16 L13 23 L15.5 21.5 L12 14.5 L18 14.5 Z"
          fill={cursorColor}
          stroke="#FFFFFF"
          strokeWidth="1.5"
          strokeLinejoin="round"
          style={{ transition: "none" }}
        />
      </svg>
      
    </AbsoluteFill>
  );
};

export default AnimatedButton;